/**
 * Text top-up: 136 plain-text documents topping Data, Lists and Notes to 50 entries each.
 *
 * GENERATED by the example generators — do not edit by hand; re-run the
 * generator instead. Bodies are plain template literals using naming
 * tokens (⟦vr:…⟧ ⟦fn:…⟧ ⟦cl:…⟧ ⟦ky:…⟧) resolved by renderTokens at
 * creation time (Settings → Editor → Naming style), then reindent
 * converts the canonical 4-space indent to the configured style.
 */
import type {FileExample} from "@/lib/examples";
import {mkExample} from "./_helpers";
import {renderTokens} from "./_tokens";

const CAT: Record<string, string> = {
    "Config data": "Data",
    "Tabular": "Data",
    "Logs": "Data",
    "Delimited": "Data",
    "Tasks": "Lists",
    "Releases": "Lists",
    "Word lists": "Lists",
    "Checklists": "Lists",
    "Daily": "Notes",
    "Meetings": "Notes",
    "Decisions": "Notes",
    "Agendas": "Notes",
    "Minutes & misc": "Notes",
};


const ex = (
    id: string, label: string, description: string, sub: string, baseName: string,
    body: string, fixedName?: string, ext: string = ".txt",
) => mkExample("text", id, label, description, CAT[sub] ?? "Data", sub, baseName, ext, (s) => renderTokens(body, s), fixedName);

